interface RemainingBenefitsFilter {
  totalMedicationLimit?: number | null;
  remainingMedicationCount?: number | null;
  totalVisitLimit?: number | null;
  remainingVisitLimit?: number | null;
}

const isDisplayablePassPolicy = (policy: UserPolicy): boolean => {
  const isExpired = Boolean(
    policy.expirationDate && new Date(policy.expirationDate) <= new Date(),
  );
  if (isExpired) {
    return false;
  }

  const isBasicPlan =
    policy.product?.displayName === 'Basic Plan' ||
    Boolean(
      Config.NEXT_PUBLIC_365_BASIC_PLAN_ID &&
        policy.planId === Config.NEXT_PUBLIC_365_BASIC_PLAN_ID,
    );
  if (isBasicPlan) {
    return false;
  }

  const remaining = policy.remainingBenefits as RemainingBenefitsFilter | null;
  if (!remaining) {
    return true;
  }

  const hasMedicationRemaining =
    Number(remaining.totalMedicationLimit) > 0 &&
    Number(remaining.remainingMedicationCount) > 0;
  const visitLimitsMissing =
    remaining.totalVisitLimit == null && remaining.remainingVisitLimit == null;
  const hasVisitRemaining =
    visitLimitsMissing ||
    (Number(remaining.totalVisitLimit) > 0 &&
      Number(remaining.remainingVisitLimit) > 0);

  return hasMedicationRemaining || hasVisitRemaining;
};

