  try {
    const data = await api.dependants();
    const dependantList: Dependants[] = Array.isArray(data?.data) ? data.data : [];
    if (dependantList.length === 0) {
      setState((prevState) => ({
        ...prevState,
        dependants: [],
        selDependant: -1,
        member_policies: [],
        activeSlide: 0,
      }));
      return;
